function esc(v=''){return String(v).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(cryptoRandom()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function cryptoRandom(){const n=new Uint32Array(1);crypto.getRandomValues(n);return n[0]/4294967296}
function randomizeQuestion(q,targetPosition=null){
  if(!Array.isArray(q.options))return {...q};
  const entries=q.options.map((text,index)=>({text,index}));
  if(Array.isArray(q.answers)){
    const order=shuffle(entries);return {...q,options:order.map(x=>x.text),answers:q.answers.map(a=>order.findIndex(x=>x.index===a)).sort((a,b)=>a-b)}
  }
  const correct=entries.find(x=>x.index===q.answer),wrong=shuffle(entries.filter(x=>x.index!==q.answer));
  const pos=Number.isInteger(targetPosition)?Math.max(0,Math.min(entries.length-1,targetPosition)):Math.floor(cryptoRandom()*entries.length);
  const order=[...wrong];order.splice(pos,0,correct);
  return {...q,options:order.map(x=>x.text),answer:pos}
}
function randomizeQuestions(items){
  const singleCount=items.filter(q=>Array.isArray(q.options)&&!Array.isArray(q.answers)).length;
  const targets=shuffle(Array.from({length:singleCount},(_,i)=>i%4));let singleIndex=0;
  return items.map(q=>Array.isArray(q.options)&&!Array.isArray(q.answers)?randomizeQuestion(q,targets[singleIndex++]):randomizeQuestion(q))
}
