function sparkle(anchor){const r=anchor.getBoundingClientRect();for(let i=0;i<12;i++){const dot=document.createElement('i');dot.className='reaction-spark';dot.style.left=(r.left+r.width/2)+'px';dot.style.top=(r.top+r.height/2)+'px';dot.style.setProperty('--dx',`${(Math.random()-.5)*180}px`);dot.style.setProperty('--dy',`${(Math.random()-.5)*130}px`);dot.style.background=['#00d8ff','#7c5cff','#00e59b','#ffd166'][i%4];document.body.appendChild(dot);setTimeout(()=>dot.remove(),900)}}
