  const active=p.name?`<article class="active-profile-card account-active-card"><div class="avatar large">${esc((p.name||'A')[0])}</div><div class="account-active-main"><span class="hero-kicker">CONTA ATUAL</span><h3>${esc(p.name)}</h3><p>${esc(CLASSES[p.classId]?.label||p.classId||'Turma não definida')} · ${isProtectedSession()?'Protegida por senha':isLegacySession()?'Formato antigo':'Sessão temporária'}</p><div class="account-progress-strip"><span><b>${activeStats.completed}</b> aulas concluídas</span><span><b>${activeStats.inProgress}</b> em andamento</span><span><b>${activeStats.results}</b> registros</span></div><small>${protectedStatus===false?'Armazenamento persistente não confirmado. Exporte um backup regularmente.':'O acesso fica bloqueado após inatividade e nunca deve permanecer aberto em computador compartilhado.'}</small></div><div class="profile-card-actions account-primary-actions"><button class="btn btn-primary btn-small" data-profile-continue>Continuar como ${esc(firstName())}</button><button class="btn btn-secondary btn-small" data-profile-switch>Trocar estudante</button><button class="btn btn-secondary btn-small" data-action="verify-progress">Verificar meu progresso</button><button class="btn btn-secondary btn-small" data-profile-lock>${isProtectedSession()?'Sair e bloquear':'Encerrar sessão'}</button>${isProtectedSession()?'<button class="btn btn-secondary btn-small" data-export-active-profile>Exportar backup</button>':'<button class="btn btn-secondary btn-small" data-action="protect-profile">Proteger agora</button>'}${isProtectedSession()?'<button class="btn btn-danger btn-small" data-delete-active-profile>Apagar dados deste perfil</button>':'<button class="btn btn-danger btn-small" data-discard-temporary>Descartar sessão temporária</button>'}</div></article>`:'';
  const otherProfiles=profiles.filter(profile=>profile.id!==activeId);
