  const renderTask=()=>{if(doneCount>=s.tasks.length){showFinished();return}index=Math.max(index,doneCount);let resolved=false;const t=s.tasks[index],tokens=shuffle(t.tokens);host.innerHTML=`<div class="question-index"><span>FÓRMULA ${index+1}</span><span>${index+1} de ${s.tasks.length}</span></div><div class="question">${esc(t.prompt)}</div><div class="formula-answer" id="formulaAnswer"><span class="helper">Clique nos blocos na ordem correta.</span></div><div class="formula-builder">${tokens.map((x,i)=>`<button class="formula-token" data-token="${i}">${esc(x)}</button>`).join('')}</div><div class="action-cluster"><button class="btn btn-secondary btn-small" data-clear>Limpar</button><button class="btn btn-primary btn-small" data-check>Verificar fórmula</button></div><div id="feedback"></div>`;const selected=[];host.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{if(resolved)return;selected.push(b.textContent);b.disabled=true;renderAnswer()});host.querySelector('[data-clear]').onclick=()=>{if(resolved)return;selected.length=0;host.querySelectorAll('[data-token]').forEach(b=>b.disabled=false);renderAnswer()};host.querySelector('[data-check]').onclick=()=>{if(resolved)return;const value=selected.join(''),ok=normalizeFormula(value)===normalizeFormula(t.answer);const f=host.querySelector('#feedback');f.className=`feedback ${ok?'good':'bad'}`;f.innerHTML=ok?`<div class="feedback-icon">✓</div><div><strong>Fórmula correta!</strong><p>${esc(t.why)}</p></div>`:`<div class="feedback-icon">!</div><div><strong>A ordem ainda não está correta.</strong><p>Você montou <code>${esc(value||'nenhum bloco')}</code>. ${esc(t.why)}</p></div>`;state.lessonRuntime.interactions++;if(ok){resolved=true;state.lessonRuntime.correct++;doneCount++;index=doneCount;saveStageCheckpoint({kind:'formula',index,doneCount});host.querySelectorAll('button').forEach(b=>b.disabled=true);popReaction(true,'Fórmula construída!');logLessonActivity('formula_completed','Fórmula construída corretamente',t.prompt,{correct:true});const fp=c.querySelector('#formulaProgress');if(fp)fp.textContent=`${doneCount}/${s.tasks.length}`;setTimeout(()=>doneCount>=s.tasks.length?showFinished():renderTask(),state.settings.reducedMotion?260:780)}else{state.lessonRuntime.errors++;saveRuntime();popReaction(false,'Fórmula incorreta','Revise os blocos e tente novamente.');logLessonActivity('formula_attempt','Tentativa de fórmula revisada',`${t.prompt} · Montagem: ${value||'vazia'}`,{correct:false})}};function renderAnswer(){const a=host.querySelector('#formulaAnswer');a.innerHTML=selected.length?selected.map(x=>`<span class="formula-token selected-token">${esc(x)}</span>`).join(''):'<span class="helper">Clique nos blocos na ordem correta.</span>'}};renderTask();
