    if(step===0){host.innerHTML=`${card}<div class="hr-workspace"><div class="hr-stage-label">1. Localize o registro que precisa de conferência</div><div class="hr-schedule"><div class="hr-row head"><span>Dia</span><span>Entrada</span><span>Saída</span><span>Intervalo</span><span>Apuração</span></div>${(cfg.schedule||[]).map((row,i)=>`<button class="hr-row" data-hr-row="${i}">${row.map(cell=>`<span>${esc(cell)}</span>`).join('')}</button>`).join('')}</div><div id="hrFeedback"></div></div>`;host.querySelectorAll('[data-hr-row]').forEach(button=>button.onclick=()=>{const selected=Number(button.dataset.hrRow);if(selected!==Number(cfg.anomalyIndex||0)){button.classList.add('wrong');fail(`Linha de jornada selecionada: ${selected+1}`);return}button.classList.add('correct');anomalySelected=true;step=1;succeed('Divergência de jornada localizada',`Registro ${selected+1} selecionado para conferência.`)})}
