    'hr-flag-anomaly':'Marcar divergência','hr-approve-reviewed':'Registrar revisão',
    'docs-title':'Aplicar título','docs-add-date':'Inserir data e versão','docs-permission-reader':'Permissão Leitor','docs-permission-commenter':'Permissão Comentador','docs-export-pdf':'Exportar PDF','files-resolve-conflict':'Resolver conflito de versão','files-review-version':'Conferir versão atual','files-approve-access':'Aprovar solicitação de acesso',
    'assets-rotate':'Inspecionar em 360°','assets-explode':'Abrir vista de componentes','assets-select-ssd':'Identificar SSD','assets-connect-printer':'Conectar impressora',
