function difficultyLabel(x){return x==='basic'?'Fundamentos':x==='intermediate'?'Intermediário':'Avançado'}
function normalizeTextAnswer(v){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'').toUpperCase()}
