  const vis=()=>{if(document.hidden)log('visibility','Aba ou aplicativo ficou oculto')};const copy=e=>{e.preventDefault();log('copy','Tentativa de copiar conteúdo')};const paste=e=>{e.preventDefault();log('paste','Tentativa de colar conteúdo')};const ctx=e=>{e.preventDefault();log('contextmenu','Menu de contexto bloqueado')};const key=e=>{if(e.key==='F12'||(e.ctrlKey&&e.shiftKey&&['I','J','C'].includes(e.key.toUpperCase()))){e.preventDefault();log('shortcut',e.key)}};document.addEventListener('visibilitychange',vis);document.addEventListener('copy',copy);document.addEventListener('paste',paste);document.addEventListener('contextmenu',ctx);document.addEventListener('keydown',key);return()=>{document.removeEventListener('visibilitychange',vis);document.removeEventListener('copy',copy);document.removeEventListener('paste',paste);document.removeEventListener('contextmenu',ctx);document.removeEventListener('keydown',key)}
