function proficiencyLevel(p){if(p<20)return'Iniciante I';if(p<35)return'Iniciante II';if(p<50)return'Básico I';if(p<63)return'Básico II';if(p<75)return'Intermediário I';if(p<85)return'Intermediário II';if(p<93)return'Avançado I';return'Avançado II'}
