function mountResult(){
  const root=document.querySelector('#resultRoot'),r=state.result;const recommendation=pickToolRecommendation({relatedAreas:r.areas?.filter(a=>a.percent>=60).map(a=>a.area)||[]});if(recommendation)recordRecommendationShown(recommendation.id);r.delivery=r.delivery||{resultExported:false,classroomOpened:false,attachedConfirmed:false,deliveredConfirmed:false};
  root.innerHTML=`<section class="panel result-hero"><span class="hero-kicker">Diagnóstico concluído</span><h2>${esc(r.diagnosticModeLabel)}</h2><p>${esc(r.student.name)} · ${CLASSES[r.selectedClass].short}</p><div class="score-ring" style="--score:${r.proficiency}%"><span>${r.proficiency}%</span></div><h3>${esc(r.classification)}</h3><p>${r.diagnosticMode==='general'?'Proficiência geral de informática':'Domínio dos conteúdos da turma'}</p></section><section class="panel panel-pad" style="margin-top:16px">${r.teacherRelease?.authorized?`<div class="info-card tip"><h4>Liberação antecipada registrada</h4><p>${esc(r.teacherRelease.note)}</p></div>`:''}<div class="metric-grid"><div class="metric"><small>Acertos</small><strong>${r.correct}/${r.answered}</strong></div><div class="metric"><small>Respondidas</small><strong>${r.answered}/${r.totalQuestions}</strong></div><div class="metric"><small>XP motivacional</small><strong>${r.xp}</strong></div><div class="metric"><small>Tempo</small><strong>${formatDuration(r.durationSeconds)}</strong></div><div class="metric"><small>Integridade</small><strong>${r.integrity.score}%</strong></div><div class="metric"><small>Validade</small><strong>${esc(r.validity||'Válido')}</strong></div></div><div class="info-card success" style="margin-top:16px"><h4>Avaliação por proficiência</h4><p>O XP é apenas um indicador motivacional. A avaliação considera proficiência, evidências, participação efetiva e critérios definidos pelo professor; XP, velocidade e elementos visuais não determinam nota.</p></div><div class="section-title"><div><h2>Desempenho por área</h2><p>As modalidades diferentes não devem ser comparadas no mesmo ranking.</p></div></div><div class="area-results">${r.areas.map(a=>`<div class="area-result"><span>${esc(a.area)}</span><div class="area-bar"><i style="width:${a.percent}%"></i></div><strong>${a.percent}%</strong></div>`).join('')}</div><div class="section-title"><div><h2>Extrato da realização</h2></div></div><div class="info-grid"><div class="info-card"><h4>Modalidade</h4><p>${esc(r.diagnosticModeLabel)}</p></div><div class="info-card"><h4>Perfil utilizado</h4><p>${r.classProfileUsed?CLASSES[r.classProfileUsed].short:'Banco geral, independente da turma'}</p></div><div class="info-card"><h4>Banco de questões</h4><p>Versão ${APP_VERSION} · ${r.totalQuestions} desafios · nível avançado ${r.advancedAccuracy??0}%</p></div><div class="info-card ${r.integrity.score>=85?'success':'tip'}"><h4>Integridade</h4><p>${r.integrity.events.length} eventos registrados · ${r.integrity.shields} escudos restantes</p></div><div class="info-card"><h4>Token de validação</h4><p class="certificate-code">${esc(r.validationToken||r.id)}</p><small>Verificação local de integridade; não equivale a assinatura digital de servidor.</small></div></div><div class="section-title"><div><h2>Revisão das respostas</h2><p>Abra cada item para conferir a resposta correta e entender o raciocínio.</p></div></div><div class="answer-review">${r.answers.map((a,i)=>`<details class="answer-detail ${a.correct?'ok':'miss'}"><summary><span>${i+1}. ${esc(a.area)}</span><strong>${a.correct?'✓ Correta':'✕ Revisar'}</strong></summary><div><h4>${esc(a.question)}</h4><p><b>Sua resposta:</b> ${esc(a.choice)}</p><p><b>Resposta correta:</b> ${esc(a.correctAnswer||'Consulte o professor')}</p><p>${esc(a.explanation)}</p></div></details>`).join('')}</div></section>${deliveryHubHTML(r,'diagnostic')}${recommendation?toolRecommendationHTML(recommendation):''}`;
  bindDeliveryHub(root,r,'diagnostic');bindToolRecommendation(root,recommendation);confetti()
}

function renderTerms(){
  if(!state.profile)return `<section class="panel panel-pad terms-page"><span class="hero-kicker">TERMOS E PRIVACIDADE</span><h2>Abra ou crie um perfil</h2><p>O aceite precisa ficar vinculado ao perfil utilizado na atividade.</p><div class="stage-actions"><button class="btn btn-primary" data-action="profile-center">Abrir Central de contas</button><button class="btn btn-secondary" data-action="home">Voltar</button></div></section>`;
  if(termsUi.profileId!==state.profile.id){termsUi.fullOpened=false;termsUi.privacyViewed=false;termsUi.reachedEnd=false;termsUi.bulkAccepted=false;termsUi.profileId=state.profile.id}
  const accepted=currentGeneralAcceptance(),history=[...getGeneralAcceptances()].reverse();
  const sections=GENERAL_TERMS.sections.map((section,index)=>`<details class="terms-section" data-term-section="${index}"><summary><span>${index+1}</span>${esc(section.title.replace(/^\d+\.\s*/,''))}</summary><p>${esc(section.text)}</p></details>`).join('');
  const historyHtml=history.length?`<div class="terms-history"><h3>Histórico do perfil</h3>${history.slice(0,10).map(record=>`<div><strong>v${esc(record.termsVersion)}</strong><span>${new Date(record.acceptedAt).toLocaleString('pt-BR')} · ${record.status==='ACCEPTED'?'Aceito':'Outro estado'}</span><code>${esc(record.acceptanceId?.slice(0,12)||'')}</code></div>`).join('')}</div>`:'';
  if(accepted)return `<section class="panel panel-pad terms-page"><div class="section-title" style="margin-top:0"><div><span class="hero-kicker">COMPROMISSO PEDAGÓGICO</span><h2>Termo vigente aceito</h2><p>Versão ${esc(GENERAL_TERMS.version)} · aceito em ${new Date(accepted.acceptedAt).toLocaleString('pt-BR')}.</p></div><span class="terms-status accepted">✓ Registro válido</span></div><div class="info-card success"><h4>Finalidade educacional</h4><p>${esc(EDUCATIONAL_USE_NOTICE.text)}</p></div><div class="action-cluster"><button class="btn btn-secondary" data-terms-full>Abrir texto completo</button><button class="btn btn-secondary" data-terms-end>Ir até o final</button><button class="btn btn-secondary" data-terms-privacy>Política de privacidade</button><button class="btn btn-secondary" data-terms-simulation>Simulações fictícias</button><button class="btn btn-secondary" data-terms-download>Baixar cópia</button></div><div id="termsFullText" class="terms-full-text">${sections}<div class="terms-end-sentinel" data-terms-sentinel><span>✓</span><strong>Fim do termo</strong><small>Você chegou à declaração final.</small></div></div>${historyHtml}<div class="stage-actions"><button class="btn btn-primary" data-terms-return>Voltar</button></div></section>`;
  return `<section class="panel panel-pad terms-page"><div class="section-title" style="margin-top:0"><div><span class="hero-kicker">LEITURA OBRIGATÓRIA · VERSÃO ${esc(GENERAL_TERMS.version)}</span><h2>${esc(GENERAL_TERMS.title)}</h2><p>Atualizado em ${new Date(GENERAL_TERMS.updatedAt+'T12:00:00').toLocaleDateString('pt-BR')}.</p></div><span class="terms-status pending">Pendente</span></div><div class="terms-summary"><strong>Resumo em linguagem simples</strong><p>${esc(GENERAL_TERMS.summary)}</p></div><div class="info-card success"><h4>Finalidade educacional</h4><p>${esc(EDUCATIONAL_USE_NOTICE.text)}</p></div><div class="terms-guided-actions"><button class="btn btn-primary" data-terms-end>⇣ Ir até o final do termo</button><button class="btn btn-secondary" data-terms-accept-all disabled>✓ Marcar todos como aceitos</button><span class="terms-reading-state" data-terms-reading-state>Leia ou use “Ir até o final” para liberar o aceite rápido.</span></div><div class="terms-reading-progress"><i data-terms-reading-progress></i></div><div class="action-cluster"><button class="btn btn-secondary" data-terms-full>Ver termo completo</button><button class="btn btn-secondary" data-terms-privacy>Ver política de privacidade</button><button class="btn btn-secondary" data-terms-simulation>Ver aviso sobre simulações</button><button class="btn btn-secondary" data-terms-download>Baixar uma cópia</button></div><div id="termsFullText" class="terms-full-text">${sections}<div class="terms-end-sentinel" data-terms-sentinel tabindex="-1"><span>✓</span><strong>Fim do termo</strong><small>Agora você pode confirmar os dois compromissos abaixo.</small></div></div><div class="terms-confirmations"><label><input type="checkbox" data-terms-read> <span>Li e compreendi o resumo e tive acesso ao texto completo.</span></label><label><input type="checkbox" data-terms-responsible> <span>Concordo em utilizar a plataforma de forma responsável e exclusivamente educacional.</span></label></div><div class="info-card tip"><h4>O que este aceite não significa</h4><p>Ele não autoriza coleta ilimitada, publicação de nome ou imagem, publicidade, venda de dados, monitoramento invasivo nem substitui autorizações institucionais ou do responsável quando necessárias.</p></div><div class="stage-actions"><button class="btn btn-secondary" data-terms-decline>Não aceitar e sair</button>${isProtectedSession()?'<button class="btn btn-secondary" data-terms-export>Exportar perfil antes de sair</button>':''}<button class="btn btn-primary" data-terms-accept disabled>Aceitar e continuar</button></div></section>`
}
function bindTermsPage(){
  const fullText=app.querySelector('#termsFullText'),sentinel=app.querySelector('[data-terms-sentinel]'),readingState=app.querySelector('[data-terms-reading-state]'),progress=app.querySelector('[data-terms-reading-progress]'),markAll=app.querySelector('[data-terms-accept-all]');
  const markReached=()=>{if(termsUi.reachedEnd)return;termsUi.reachedEnd=true;if(markAll)markAll.disabled=false;if(readingState)readingState.textContent='Fim alcançado. Você pode marcar os dois compromissos de uma vez.';if(progress)progress.style.width='100%';sentinel?.classList.add('reached')};
  const expandAndReach=()=>{termsUi.fullOpened=true;fullText?.classList.add('highlight');fullText?.querySelectorAll('details').forEach(item=>item.open=true);markReached();sentinel?.scrollIntoView({behavior:state.settings.reducedMotion?'auto':'smooth',block:'center'});setTimeout(()=>sentinel?.focus({preventScroll:true}),state.settings.reducedMotion?0:500)};
  const full=app.querySelector('[data-terms-full]');if(full)full.onclick=()=>{termsUi.fullOpened=true;fullText?.scrollIntoView({behavior:state.settings.reducedMotion?'auto':'smooth',block:'start'});fullText?.classList.add('highlight');fullText?.querySelector('details')?.setAttribute('open','')};
  app.querySelectorAll('[data-terms-end]').forEach(button=>button.onclick=expandAndReach);
  app.querySelector('[data-terms-privacy]')?.addEventListener('click',()=>{termsUi.privacyViewed=true;openPrivacyNotice()});
  app.querySelector('[data-terms-simulation]')?.addEventListener('click',openSimulationNotice);
  app.querySelector('[data-terms-download]')?.addEventListener('click',downloadTermsCopy);
  app.querySelector('[data-terms-export]')?.addEventListener('click',downloadProfileBackup);
  app.querySelector('[data-terms-return]')?.addEventListener('click',()=>setView(state.returnView==='terms'?'home':state.returnView));
  const read=app.querySelector('[data-terms-read]'),responsible=app.querySelector('[data-terms-responsible]'),accept=app.querySelector('[data-terms-accept]');
  const update=()=>{if(accept)accept.disabled=!(read?.checked&&responsible?.checked)};
  read?.addEventListener('change',update);responsible?.addEventListener('change',update);
  markAll?.addEventListener('click',()=>{if(!termsUi.reachedEnd)return;if(read)read.checked=true;if(responsible)responsible.checked=true;termsUi.bulkAccepted=true;markAll.classList.add('done');markAll.textContent='✓ Todos os compromissos marcados';update();accept?.focus()});
  if(sentinel&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){markReached();observer.disconnect()}},{threshold:.7});observer.observe(sentinel)}
  accept?.addEventListener('click',acceptCurrentTerms);app.querySelector('[data-terms-decline]')?.addEventListener('click',declineCurrentTerms)
}
async function acceptCurrentTerms(){
  const previous=getGeneralAcceptances().at(-1);const record=buildGeneralAcceptance({profileId:state.profile.id,classId:state.profile.classId,termsHash:TERMS_RUNTIME.termsHash,deviceSessionId:DEVICE_SESSION_ID,fullTermsOpened:termsUi.fullOpened,privacyNoticeViewed:termsUi.privacyViewed,reachedEnd:termsUi.reachedEnd,bulkAccepted:termsUi.bulkAccepted,previousAcceptanceId:previous?.acceptanceId||''});await saveGeneralAcceptance(record);termsUi.fullOpened=false;termsUi.privacyViewed=false;termsUi.reachedEnd=false;termsUi.bulkAccepted=false;toast('Termo aceito e registrado no perfil.','good');setView(state.returnView==='terms'?'home':state.returnView)
}
async function declineCurrentTerms(){if(!confirm('Sem aceitar a versão vigente, novas atividades permanecerão bloqueadas. Encerrar esta sessão?'))return;await lockActiveProfile('terms-declined');state.profile=null;state.view='profile';render();toast('Sessão encerrada sem novo aceite. O perfil e o progresso anterior foram preservados.','warn',6000)}
