function openPrivacyNotice(){const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card wide-modal"><span class="hero-kicker">PRIVACIDADE · VERSÃO ${esc(PRIVACY_NOTICE.version)}</span><h2>${esc(PRIVACY_NOTICE.title)}</h2><ul class="privacy-list">${PRIVACY_NOTICE.points.map(point=>`<li>${esc(point)}</li>`).join('')}</ul><h3>Permissões declaradas</h3><div class="permission-list">${PERMISSIONS_MANIFEST.permissions.map(item=>`<article><strong>${esc(item.permission)}</strong><p>${esc(item.educationalPurpose)}</p><small>Alternativa: ${esc(item.fallbackMode)}</small></article>`).join('')}</div><div class="info-card success"><h4>Não solicitado nesta versão</h4><p>${PERMISSIONS_MANIFEST.explicitlyNotRequested.map(esc).join(', ')}.</p></div><button class="btn btn-primary" data-close>Fechar</button></div>`;document.body.appendChild(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove()}
