function ensureActivityAcceptance(activityKey){
  const existing=currentActivityAcceptance(activityKey);if(existing)return Promise.resolve(existing);const rules=ACTIVITY_RULES[activityKey];if(!rules)return Promise.reject(new Error('Regras da atividade não configuradas.'));
  return new Promise(resolve=>{const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><span class="hero-kicker">REGRAS ESPECÍFICAS · VERSÃO ${esc(rules.version)}</span><h2>${esc(rules.title)}</h2><p>Leia antes de iniciar. Este aceite fica separado do termo geral.</p><ul class="activity-rules-list">${rules.rules.map(rule=>`<li>${esc(rule)}</li>`).join('')}</ul>${rules.teacherAuthorizationRequired?'<div class="info-card tip"><h4>Autorização do professor</h4><p>O início ou uma exceção pode exigir EduAuth, com escopo limitado à ação solicitada.</p></div>':''}<label class="terms-activity-check"><input type="checkbox"> <span>Li e compreendi as regras desta atividade.</span></label><div class="stage-actions"><button class="btn btn-secondary" data-cancel>Cancelar</button><button class="btn btn-primary" data-accept disabled>Aceitar regras e continuar</button></div></div>`;document.body.appendChild(modal);const check=modal.querySelector('input'),accept=modal.querySelector('[data-accept]');check.onchange=()=>accept.disabled=!check.checked;modal.querySelector('[data-cancel]').onclick=()=>{modal.remove();resolve(null)};accept.onclick=async()=>{const general=currentGeneralAcceptance();const record=buildActivityAcceptance({profileId:state.profile.id,classId:state.profile.classId,activityKey,rulesHash:TERMS_RUNTIME.activityHashes[activityKey],deviceSessionId:DEVICE_SESSION_ID,generalAcceptanceId:general?.acceptanceId||''});await saveActivityAcceptance(record);modal.remove();toast('Regras da atividade registradas.','good');resolve(record)}})
}
