function openSettings(){
  const s=state.settings,modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card wide-modal"><h2>Acessibilidade, perfil e preferências</h2><div class="settings-grid"><div class="setting-row"><div><strong>Tema visual</strong><div class="helper">Escolha o fundo mais confortável para leitura.</div></div><select class="select" style="width:170px" id="themeMode"><option value="dark">Escuro</option><option value="light">Claro</option><option value="system">Usar o aparelho</option></select></div><div class="setting-row"><div><strong>Tamanho da fonte</strong><div class="helper">Ajuste textos e botões.</div></div><select class="select" style="width:150px" id="fontScale"><option value="0.9">Menor</option><option value="1">Padrão</option><option value="1.15">Grande</option><option value="1.3">Muito grande</option></select></div><div class="setting-row"><div><strong>Contraste elevado</strong><div class="helper">Aumenta a diferença entre fundo e texto.</div></div><button class="switch ${s.highContrast?'on':''}" data-toggle="highContrast" aria-label="Alternar contraste elevado"></button></div><div class="setting-row"><div><strong>Reduzir animações</strong><div class="helper">Mantém o conteúdo com movimentos mínimos.</div></div><button class="switch ${s.reducedMotion?'on':''}" data-toggle="reducedMotion" aria-label="Alternar redução de animações"></button></div><div class="setting-row"><div><strong>Modo de leitura</strong><div class="helper">Aumenta espaçamento e altura das linhas.</div></div><button class="switch ${s.readingMode?'on':''}" data-toggle="readingMode" aria-label="Alternar modo de leitura"></button></div><div class="setting-row"><div><strong>Lembretes de horário escolar</strong><div class="helper">Mostra aula atual e tempo aproximado restante.</div></div><button class="switch ${s.showScheduleNotifications!==false?'on':''}" data-toggle="showScheduleNotifications" aria-label="Alternar lembretes de horário"></button></div><div class="setting-row"><div><strong>Descoberta de ferramentas</strong><div class="helper">Recomenda ocasionalmente outros recursos educacionais.</div></div><button class="switch ${s.recommendationsEnabled!==false?'on':''}" data-toggle="recommendationsEnabled" aria-label="Alternar recomendações"></button></div><div class="setting-row"><div><strong>Explicações</strong><div class="helper">Escolha o nível padrão.</div></div><select class="select" style="width:170px" id="explanationMode"><option value="objective">Objetivas</option><option value="detailed">Detalhadas</option><option value="step">Passo a passo</option></select></div></div><div class="section-title"><div><h3>Perfil e continuidade</h3><p>${isProtectedSession()?'O backup permanece criptografado e exige a senha original.':'Esta sessão ainda não possui proteção persistente.'}</p></div></div><div class="action-cluster">${isProtectedSession()?'<button class="btn btn-secondary btn-small" data-export-profile>Exportar backup do perfil</button>':'<button class="btn btn-primary btn-small" data-protect-profile>Proteger perfil</button>'}<label class="btn btn-secondary btn-small">Importar perfil<input type="file" accept=".edu-profile,application/json" hidden data-import-profile-settings></label><button class="btn btn-secondary btn-small" data-profile-center>Gerenciar perfis</button><button class="btn btn-secondary btn-small" data-settings-terms>Termos aceitos</button><button class="btn btn-secondary btn-small" data-settings-privacy>Privacidade</button></div><div class="stage-actions"><button class="btn btn-primary" data-save>Salvar preferências</button><button class="btn btn-secondary" data-close>Fechar</button></div></div>`;document.body.appendChild(modal);modal.querySelector('#themeMode').value=s.theme||'dark';modal.querySelector('#fontScale').value=String(s.fontScale);modal.querySelector('#explanationMode').value=s.explanationMode;modal.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>b.classList.toggle('on'));modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-save]').onclick=()=>{state.settings={...state.settings,fontScale:Number(modal.querySelector('#fontScale').value),theme:modal.querySelector('#themeMode').value,highContrast:modal.querySelector('[data-toggle="highContrast"]').classList.contains('on'),reducedMotion:modal.querySelector('[data-toggle="reducedMotion"]').classList.contains('on'),readingMode:modal.querySelector('[data-toggle="readingMode"]').classList.contains('on'),showScheduleNotifications:modal.querySelector('[data-toggle="showScheduleNotifications"]').classList.contains('on'),recommendationsEnabled:modal.querySelector('[data-toggle="recommendationsEnabled"]').classList.contains('on'),explanationMode:modal.querySelector('#explanationMode').value};saveSettings(state.settings);applySettings();modal.remove();render();toast('Preferências salvas.','good')};modal.querySelector('[data-protect-profile]')?.addEventListener('click',()=>{modal.remove();openProtectProfile()});modal.querySelector('[data-export-profile]')?.addEventListener('click',downloadProfileBackup);modal.querySelector('[data-profile-center]').onclick=()=>{modal.remove();state.returnView=state.view;setView('profile')};modal.querySelector('[data-settings-terms]').onclick=()=>{modal.remove();state.returnView=state.view;setView('terms')};modal.querySelector('[data-settings-privacy]').onclick=openPrivacyNotice;modal.querySelector('[data-import-profile-settings]').onchange=async e=>{try{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024)throw new Error('O arquivo excede o limite de 5 MB.');await importProfilePackage(JSON.parse(await file.text()));toast('Perfil importado. Abra a Central de perfis para desbloquear.','good')}catch(err){toast('Não foi possível importar: '+esc(err.message),'bad')}}
}

function resetIdleLock(){clearTimeout(idleHandle);if(!isProtectedSession())return;idleHandle=setTimeout(async()=>{await lockActiveProfile();state.profile=null;state.view='profile';render();toast('Perfil bloqueado após 10 minutos sem atividade.','warn',5000)},10*60*1000)}
function openProfileUnlock(profileId){const profile=getProfileList().find(p=>p.id===profileId),modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><span class="hero-kicker">DESBLOQUEAR PERFIL</span><h2>${esc(profile?.displayName||'Perfil')}</h2><p>${esc(CLASSES[profile?.classId]?.label||'')}</p><div class="field"><label>Senha local</label><input class="input" type="password" autocomplete="current-password"></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" data-unlock>Desbloquear</button></div></div>`;document.body.appendChild(modal);const input=modal.querySelector('input');input.focus();const unlock=async()=>{try{await unlockProtectedProfile(profileId,input.value);storageDiagnostics=await getStorageDiagnostics();state.profile=getProfile();state.settings=getSettings();applySettings();modal.remove();continueAfterProfile();toast('Perfil desbloqueado.','good');resetIdleLock()}catch(err){toast(esc(err.message),'bad');input.select()}};modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-unlock]').onclick=unlock;input.onkeydown=e=>{if(e.key==='Enter')unlock()}}

function openProfileRecovery(profileId){
  const profile=getProfileList().find(p=>p.id===profileId);if(!profile)return;
  const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><span class="hero-kicker">RECUPERAÇÃO EDUAUTH</span><h2>Preparar redefinição de senha</h2><p>Este fluxo não revela a senha antiga. Ele exporta o envelope criptográfico do perfil e gera uma solicitação vinculada a este perfil e a esta sessão.</p><div class="info-card tip"><h4>Integração em duas fases</h4><p>O envelope já está implementado, mas a redefinição completa dependerá do EduAuth Professor com a chave privada de recuperação de produção. Esta versão usa somente chaves de teste.</p></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" data-prepare>Preparar solicitação</button></div></div>`;document.body.appendChild(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-prepare]').onclick=async()=>{modal.remove();try{const envelope=await exportProfileRecoveryEnvelope(profileId);await showEduAuthAuthorization({modeName:'PROFILE_RECOVERY_ENVELOPE',actionId:'profile-recovery',classId:profile.classId,lessonId:'platform-general',activityId:'profile',profileId,resourceId:`profile-${profileId.slice(0,8)}`,title:'Redefinir senha do perfil',description:'Informe o código-base ao professor. A autorização será válida apenas para este perfil e esta sessão.',labels:{classLabel:CLASSES[profile.classId]?.label||profile.classId,subjectLabel:'Perfil local protegido',lessonLabel:profile.displayName},onAuthorized:()=>{downloadJSON(envelope,`recuperacao-${profileId.slice(0,8)}.eduauth-recovery`);toast('Pacote de recuperação exportado. A redefinição final depende do EduAuth Professor provisionado.','warn',7000)}})}catch(error){toast(esc(error.message),'bad',7000)}}
}

async function refreshStorageDiagnostics(){storageDiagnostics=await getStorageDiagnostics();return storageDiagnostics}
async function openProgressVerification(){
  const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card progress-verification-modal"><span class="hero-kicker">VERIFICAÇÃO DO PROGRESSO</span><h2>Conferindo o salvamento</h2><div class="verification-loading"><i></i><p>Gravando alterações pendentes e lendo novamente o perfil protegido…</p></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Fechar</button></div></div>`;document.body.appendChild(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove();
  try{saveRuntime();const result=await verifyActiveProgress();await refreshStorageDiagnostics();const card=modal.querySelector('.modal-card');if(result.temporary){card.innerHTML=`<span class="hero-kicker">SESSÃO TEMPORÁRIA</span><h2>Este progresso ainda não está protegido</h2><div class="info-card warning"><h4>Atenção</h4><p>${esc(result.message)}</p></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Fechar</button><button class="btn btn-primary" data-protect>Proteger perfil</button></div>`;card.querySelector('[data-close]').onclick=()=>modal.remove();card.querySelector('[data-protect]').onclick=()=>{modal.remove();openProtectProfile()};return}
    const saved=new Date(result.lastSavedAt).toLocaleString('pt-BR'),expiry=new Date(result.expiresAt).toLocaleString('pt-BR');card.innerHTML=`<span class="hero-kicker">PROGRESSO VERIFICADO</span><h2>${result.ok?'Seus dados estão salvos':'Foi encontrada uma diferença'}</h2><div class="verification-result ${result.ok?'good':'warn'}"><b>${result.ok?'✓':'!'}</b><div><strong>${esc(result.profileName)}</strong><span>Último salvamento: ${esc(saved)}</span><span>Retenção renovada até: ${esc(expiry)}</span><span>Fonte conferida: ${esc(result.source)}</span></div></div><div class="storage-metric-grid"><article><b>${result.completedLessons}</b><span>aulas concluídas</span></article><article><b>${result.inProgressLessons}</b><span>em andamento</span></article><article><b>${result.resultsCount}</b><span>resultados</span></article><article><b>${result.redundant?'Ativo':'Indisponível'}</b><span>checkpoint redundante</span></article></div><div class="info-card tip"><h4>Último ponto de atividade</h4><p>${result.lastProgressAt?`Registro em ${esc(new Date(result.lastProgressAt).toLocaleString('pt-BR'))}.`:'Nenhuma aula iniciada neste perfil.'}</p></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Fechar</button><button class="btn btn-secondary" data-storage>Diagnóstico</button><button class="btn btn-primary" data-backup>Fazer backup</button></div>`;card.querySelector('[data-close]').onclick=()=>modal.remove();card.querySelector('[data-storage]').onclick=()=>{modal.remove();openStorageDiagnostics()};card.querySelector('[data-backup]').onclick=downloadProfileBackup;updateSaveStatusUI()}catch(error){modal.querySelector('.modal-card').innerHTML=`<span class="hero-kicker">VERIFICAÇÃO INCOMPLETA</span><h2>Não foi possível confirmar o salvamento</h2><div class="info-card warning"><h4>O que aconteceu</h4><p>${esc(error.message)}</p></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Fechar</button><button class="btn btn-primary" data-storage>Diagnosticar</button></div>`;modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-storage]').onclick=()=>{modal.remove();openStorageDiagnostics()}}
}
async function openStorageDiagnostics(){
  const diagnostic=await refreshStorageDiagnostics(),modal=document.createElement('div');modal.className='modal';const privateText=diagnostic.privateModeSuspected?'Possível modo anônimo/privado ou armazenamento temporário detectado.':'Nenhum indício forte de modo privado foi detectado.';
  modal.innerHTML=`<div class="modal-card wide-modal storage-diagnostic-modal"><span class="hero-kicker">DIAGNÓSTICO DO NAVEGADOR</span><h2>Saúde do armazenamento</h2><p>Esta verificação não lê contas externas. Ela consulta somente as capacidades locais do navegador.</p><div class="storage-diagnostic-grid"><article class="${diagnostic.indexedDBAvailable?'good':'bad'}"><b>${diagnostic.indexedDBAvailable?'✓':'!'}</b><strong>IndexedDB</strong><span>${diagnostic.indexedDBAvailable?'Disponível':'Indisponível'}</span></article><article class="${diagnostic.redundantCheckpointAvailable?'good':'warn'}"><b>${diagnostic.redundantCheckpointAvailable?'✓':'!'}</b><strong>Checkpoint redundante</strong><span>${diagnostic.redundantCheckpointAvailable?'Disponível':'Ainda não criado'}</span></article><article class="${diagnostic.persistentStorage?'good':'warn'}"><b>${diagnostic.persistentStorage?'✓':'!'}</b><strong>Persistência</strong><span>${diagnostic.persistentStorage?'Confirmada':'Não confirmada'}</span></article><article class="${diagnostic.privateModeSuspected?'warn':'good'}"><b>${diagnostic.privateModeSuspected?'!':'✓'}</b><strong>Modo privado</strong><span>${esc(privateText)}</span></article></div><div class="storage-usage-panel"><div><strong>Uso estimado</strong><span>${formatStorageBytes(diagnostic.usage)} de ${diagnostic.quota?formatStorageBytes(diagnostic.quota):'limite não informado'}${diagnostic.quota?` · ${diagnostic.usagePercent}%`:''}</span></div><div><strong>Retenção local</strong><span>10 dias após o último salvamento bem-sucedido</span></div><div><strong>Falhas temporárias detectadas</strong><span>${diagnostic.indexedDbFailures}</span></div>${diagnostic.lastError?`<div class="storage-last-error"><strong>Último aviso</strong><span>${esc(diagnostic.lastError)}</span></div>`:''}</div><div class="info-card tip"><h4>Recomendação</h4><p>${diagnostic.privateModeSuspected||!diagnostic.persistentStorage?'Evite fechar a guia antes de gerar um backup. Quando possível, use uma janela normal do navegador.':'O armazenamento está em condição adequada. Mesmo assim, faça backup ao encerrar uma sequência importante.'}</p></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Fechar</button><button class="btn btn-secondary" data-retry>Tentar reconectar</button>${isProtectedSession()?'<button class="btn btn-primary" data-backup>Fazer backup</button>':''}</div></div>`;document.body.appendChild(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-backup]')?.addEventListener('click',downloadProfileBackup);modal.querySelector('[data-retry]').onclick=async e=>{const b=e.currentTarget;b.disabled=true;b.textContent='Reconectando…';storageDiagnostics=await retryStorageConnection();modal.remove();render();toast(storageDiagnostics.indexedDBAvailable?'Armazenamento reconectado e checkpoints sincronizados.':'O IndexedDB continua indisponível; mantenha um backup.',storageDiagnostics.indexedDBAvailable?'good':'warn',5200)}
}

function openProfileDelete(profileId){const profile=getProfileList().find(p=>p.id===profileId),modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><span class="hero-kicker">REMOVER DESTE COMPUTADOR</span><h2>${esc(profile?.displayName||'Perfil')}</h2><p>Esta ação remove o perfil protegido, o checkpoint redundante e todo o progresso armazenado neste navegador.</p><div class="info-card warning"><h4>Faça um backup antes</h4><p>Sem o arquivo <code>.edu-profile</code>, a exclusão pode ser irreversível. Resultados já enviados ao Classroom não são apagados.</p></div>${state.profile?.id===profileId&&isProtectedSession()?'<button class="btn btn-secondary btn-small" data-backup-before-delete>Fazer backup antes de apagar</button>':''}<div class="field"><label>Senha local do perfil</label><input class="input" type="password" autocomplete="current-password"></div><label class="delete-confirm-check"><input type="checkbox" data-understand-delete><span>Entendo que o perfil e o progresso local serão apagados deste aparelho.</span></label><div class="stage-actions"><button class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-danger" data-delete disabled>Apagar perfil e progresso</button></div></div>`;document.body.appendChild(modal);const input=modal.querySelector('input[type="password"]'),check=modal.querySelector('[data-understand-delete]'),remove=modal.querySelector('[data-delete]');input.focus();const sync=()=>remove.disabled=!check.checked||!input.value;check.onchange=sync;input.oninput=sync;modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-backup-before-delete]')?.addEventListener('click',downloadProfileBackup);remove.onclick=async()=>{if(!confirm(`Última confirmação: apagar ${profile?.displayName||'este perfil'} e todo o progresso local?`))return;remove.disabled=true;remove.textContent='Apagando…';try{await deleteProtectedProfile(profileId,input.value);state.profile=null;state.settings=getSettings();storageDiagnostics=await getStorageDiagnostics();modal.remove();render();toast('Perfil, progresso e checkpoint redundante removidos deste computador.','good')}catch(err){remove.disabled=false;remove.textContent='Apagar perfil e progresso';toast(esc(err.message),'bad');input.select()}}}

function openProtectProfile(){if(!state.profile){state.returnView=state.view;setView('profile');return}const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><span class="hero-kicker">PROTEGER PERFIL</span><h2>Crie uma senha local</h2><p>Ela será usada para criptografar o progresso. Não utilize a senha do Google, Classroom, e-mail ou GitHub.</p><div class="form-grid"><div class="field"><label>Nova senha</label><input class="input" id="protectPassword" type="password" minlength="6" autocomplete="new-password"></div><div class="field"><label>Confirmar senha</label><input class="input" id="protectConfirm" type="password" minlength="6" autocomplete="new-password"></div></div><div class="info-card tip"><h4>Atenção</h4><p>Sem a senha e sem um backup válido, o perfil poderá ficar inacessível. O perfil utiliza envelope de recuperação EduAuth. A redefinição completa dependerá do EduAuth Professor provisionado com a chave privada institucional.</p></div><div class="stage-actions"><button class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" data-protect>Proteger perfil</button></div></div>`;document.body.appendChild(modal);const pass=modal.querySelector('#protectPassword'),confirm=modal.querySelector('#protectConfirm');pass.focus();modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-protect]').onclick=async()=>{if(pass.value!==confirm.value){toast('As senhas não coincidem.','bad');return}try{if(isLegacySession())await migrateLegacyToProtected(pass.value);else await protectCurrentTemporaryProfile(pass.value);storageDiagnostics=await getStorageDiagnostics();state.profile=getProfile();state.settings=getSettings();modal.remove();render();toast('Perfil protegido com sucesso.','good')}catch(err){toast(esc(err.message),'bad')}}}
async function downloadProfileBackup(){try{const pkg=await exportActiveProfilePackage();downloadJSON(pkg,`perfil-educacional-${safeFileName(state.profile?.name||'estudante')}.edu-profile`);toast('Backup criptografado gerado. Guarde a senha separadamente.','good')}catch(err){toast(esc(err.message),'bad')}}
function openScheduleInfo(){const context=currentSchedule(),modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><span class="hero-kicker">HORÁRIO ESCOLAR</span><h2>${esc(context?.label||'Horário não identificado')}</h2><p>${esc(context?.message||'Selecione uma turma para ver o horário.')}</p><div class="info-grid"><div class="info-card"><h4>Turma</h4><p>${esc(CLASSES[state.profile?.classId]?.label||'Não selecionada')}</p></div><div class="info-card"><h4>Fuso institucional</h4><p>America/Sao_Paulo</p></div><div class="info-card"><h4>Tempo da atividade</h4><p>Tempo mínimo para liberar o comprovante: 5 minutos de sessão. A execução típica continua planejada para 15–25 minutos; o prazo do Classroom é independente.</p></div><div class="info-card tip"><h4>Prazo</h4><p>Confira o prazo diretamente no Google Classroom, pois não há um prazo específico configurado nesta versão.</p></div></div><div class="stage-actions"><button class="btn btn-primary" data-close>Entendi</button></div></div>`;document.body.appendChild(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove()}
function openAbout(){const c=PROJECT_CREDITS,modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card wide-modal"><span class="hero-kicker">SOBRE O PROJETO</span><h2>${esc(c.projectTitle)}</h2><p>${esc(c.shortDescription)}</p><div class="info-grid"><div class="info-card success"><h4>Idealização e direção pedagógica</h4><p>${esc(c.lead.name)} · ${c.lead.roles.map(esc).join(', ')}</p></div><div class="info-card"><h4>Contexto</h4><p>${esc(c.institution)} · ${esc(c.program)}</p></div><div class="info-card"><h4>Colaboração</h4><p>${c.collaborators.studentGroups.map(esc).join(', ')} e ${esc(c.collaborators.teachers)}.</p></div><div class="info-card extra"><h4>Assistência tecnológica</h4><p>${esc(c.aiAssistance.tool)} · ${esc(c.aiAssistance.model)} · ${esc(c.aiAssistance.mode)}. Validação humana: ${esc(c.aiAssistance.humanValidation)}.</p></div></div><p>A inteligência artificial é utilizada como ferramenta de apoio. As decisões pedagógicas, os testes, a seleção das funcionalidades e a validação final são realizados pelo professor.</p><div class="info-card success"><h4>Finalidade educacional e avaliação</h4><p>${esc(EDUCATIONAL_USE_NOTICE.text)}</p><p>Esta plataforma não possui loja, carteira, moedas, inventário ou compras. O XP é motivacional e não determina nota.</p></div><div class="action-cluster"><button class="btn btn-secondary btn-small" data-about-terms>Termos e compromissos</button><button class="btn btn-secondary btn-small" data-about-privacy>Privacidade</button><button class="btn btn-secondary btn-small" data-about-simulation>Simulações fictícias</button></div><h3>Histórico de versões</h3><div class="changelog-list">${CHANGELOG.map(v=>`<details><summary><strong>v${esc(v.version)} — ${new Date(v.date+'T12:00:00').toLocaleDateString('pt-BR')}</strong><span>${esc(v.title)}</span></summary><p>${esc(v.summary)}</p><ul>${v.changes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>Validado por ${esc(v.validatedBy)} · ${esc(v.ai.model)}</small></details>`).join('')}</div><div class="stage-actions"><button class="btn btn-primary" data-close>Fechar</button></div></div>`;document.body.appendChild(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-about-terms]').onclick=()=>{modal.remove();state.returnView=state.view;setView('terms')};modal.querySelector('[data-about-privacy]').onclick=openPrivacyNotice;modal.querySelector('[data-about-simulation]').onclick=openSimulationNotice}
function openToolCatalog(){const items=getToolCatalog(),modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card wide-modal"><span class="hero-kicker">REDE EDUCACIONAL</span><h2>Conheça outras ferramentas</h2><p>Recursos do ecossistema educacional do professor Gabriel. Itens sem link aparecem apenas com o estado atual do projeto.</p><div class="tool-catalog-grid">${items.map(item=>`<article class="tool-card"><div class="tool-icon">${item.icon}</div><div><span class="tool-status ${item.status}">${esc(item.statusLabel)}</span><h3>${esc(item.name)}</h3><p>${esc(item.shortDescription)}</p><div class="tag-row">${item.categories.map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')}</div></div>${item.canOpen?`<button class="btn btn-primary btn-small" data-open-tool="${item.id}">Abrir ferramenta</button>`:'<button class="btn btn-secondary btn-small" disabled>Link ainda não configurado</button>'}</article>`).join('')}</div><div class="stage-actions"><button class="btn btn-secondary" data-snooze>Não mostrar recomendações por 30 minutos</button><button class="btn btn-primary" data-close>Fechar</button></div></div>`;document.body.appendChild(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove();modal.querySelector('[data-snooze]').onclick=()=>{snoozeRecommendations(30);modal.remove();toast('Recomendações pausadas por 30 minutos.','good')};modal.querySelectorAll('[data-open-tool]').forEach(b=>b.onclick=()=>{const item=items.find(x=>x.id===b.dataset.openTool);if(item?.url){recordRecommendationOpened(item.id);window.open(item.url,'_blank','noopener,noreferrer')}})}
function toolRecommendationHTML(item){return `<aside class="panel tool-recommendation" data-recommendation="${item.id}"><button class="recommendation-close" data-recommendation-close aria-label="Fechar recomendação">×</button><div class="tool-icon">${item.icon}</div><div><span class="hero-kicker">VOCÊ SABIA?</span><h3>${esc(item.name)}</h3><p>${esc(item.shortDescription)}</p><div class="action-cluster">${item.url&&item.status==='available'?'<button class="btn btn-primary btn-small" data-recommendation-open>Conhecer</button>':''}<button class="btn btn-secondary btn-small" data-recommendation-snooze>Não mostrar por 30 minutos</button></div></div></aside>`}
function bindToolRecommendation(root,item){if(!item)return;const host=root.querySelector(`[data-recommendation="${item.id}"]`);if(!host)return;host.querySelector('[data-recommendation-close]').onclick=()=>{recordRecommendationClosed(item.id);host.remove()};host.querySelector('[data-recommendation-snooze]').onclick=()=>{snoozeRecommendations(30);host.remove()};host.querySelector('[data-recommendation-open]')?.addEventListener('click',()=>{recordRecommendationOpened(item.id);window.open(item.url,'_blank','noopener,noreferrer')})}
function deliveryFileName(record,kind){return kind==='guided'?`conclusao-${record.lessonId}-${safeName(record.student?.name||'estudante')}.pdf`:`resultado-${record.diagnosticMode}-${safeName(record.student?.name||'estudante')}.pdf`}
function deliveryCurrentStep(delivery){if(!delivery.resultExported)return 'resultExported';if(!delivery.classroomOpened)return 'classroomOpened';if(!delivery.attachedConfirmed)return 'attachedConfirmed';if(!delivery.deliveredConfirmed)return 'deliveredConfirmed';return 'complete'}
function deliveryStepMeta(key){return ({resultExported:{number:'1',title:'Baixar o resultado em PDF',detail:'Clique no botão destacado e confira o arquivo na pasta Downloads.'},classroomOpened:{number:'2',title:'Abrir a atividade no Classroom',detail:'Leia as instruções e abra o Google Classroom com a conta escolar.'},attachedConfirmed:{number:'3',title:'Anexar o PDF',detail:'Em Seu trabalho, escolha Adicionar ou criar → Arquivo → Fazer upload.'},deliveredConfirmed:{number:'4',title:'Entregar a atividade',detail:'Espere o upload terminar e clique em Entregar ou Marcar como concluída.'}})[key]}
function deliveryGuideHTML(record,kind,{opening=false}={}){const file=deliveryFileName(record,kind);return `<div class="modal-card wide-modal classroom-guide-card" role="document"><span class="hero-kicker">PASSO A PASSO DE ENTREGA</span><h2>Como anexar o PDF no Google Classroom</h2><div class="delivery-attention critical"><b>!</b><div><strong>Baixar o PDF não envia a atividade automaticamente.</strong><span>A entrega só termina depois que o arquivo carregar no Classroom e você clicar em <b>Entregar</b> ou <b>Marcar como concluída</b>.</span></div></div><ol class="classroom-guide-steps"><li><b>Entre na turma e na disciplina corretas.</b><span>Confirme o nome da turma antes de continuar.</span></li><li><b>Abra a atividade solicitada pelo professor.</b><span>Leia o título e clique em <strong>Ver instruções</strong>, quando essa opção aparecer.</span></li><li><b>Localize a área “Seu trabalho”.</b><span>Clique em <strong>Adicionar ou criar</strong> — em algumas telas pode aparecer como <strong>Adicionar trabalho</strong>.</span></li><li><b>Escolha Arquivo e depois Fazer upload.</b><span>Clique em Procurar e abra a pasta <strong>Downloads</strong> do aparelho.</span></li><li><b>Selecione o arquivo correto.</b><code>${esc(file)}</code><span>Aguarde até o nome do PDF aparecer anexado na atividade.</span></li><li><b>Finalize no Classroom.</b><span>Clique em <strong>Entregar</strong> ou <strong>Marcar como concluída</strong> e confirme a ação.</span></li><li><b>Volte para esta plataforma.</b><span>Marque “Já anexei o PDF” e “Já cliquei em Entregar”.</span></li></ol><div class="info-card tip"><h4>Não encontrou o arquivo?</h4><p>Abra Arquivos/Meus Arquivos → Downloads e procure pelo nome acima. No Chromebook, use o aplicativo Arquivos. No celular, o seletor pode aparecer como Arquivos, Downloads ou Documentos.</p></div><div class="stage-actions"><button class="btn btn-secondary" data-classroom-guide-close>${opening?'Voltar':'Fechar'}</button>${opening?'<button class="btn btn-primary" data-classroom-guide-open>Entendi e abrir o Classroom</button>':''}</div></div>`}
function deliveryHubHTML(record,kind){
  const d=record.delivery||{},current=deliveryCurrentStep(d),file=deliveryFileName(record,kind),ready=kind!=='guided'||pdfReleaseReady(record);
  const steps=['resultExported','classroomOpened','attachedConfirmed','deliveredConfirmed'].map(key=>{const meta=deliveryStepMeta(key),done=Boolean(d[key]),active=current===key,locked=(key==='classroomOpened'&&!d.resultExported)||(key==='attachedConfirmed'&&(!d.resultExported||!d.classroomOpened))||(key==='deliveredConfirmed'&&!d.attachedConfirmed);return `<button class="delivery-step ${done?'done':''} ${active?'current':''} ${locked?'locked':''}" data-delivery-state="${key}" ${locked?'disabled':''}><b>${done?'✓':meta.number}</b><span><strong>${meta.title}</strong><small>${meta.detail}</small></span>${active?'<i>Faça agora</i>':''}</button>`}).join('');
  return `<section class="panel panel-pad delivery-hub ${current==='complete'?'delivery-complete':''}" style="margin-top:16px"><div class="delivery-attention critical"><b>!</b><div><strong>ATENÇÃO: a atividade só está entregue depois do envio no Google Classroom.</strong><span>Siga os quatro passos abaixo. A plataforma não consegue verificar automaticamente o upload feito no Classroom.</span></div></div><div class="section-title delivery-title" style="margin-top:18px"><div><span class="hero-kicker">CONCLUSÃO E ENTREGA</span><h2>${current==='complete'?'Procedimento declarado como concluído':'Realize o próximo passo destacado'}</h2><p>${current==='complete'?'Você informou que anexou o arquivo e clicou em Entregar no Classroom.':'Complete um passo de cada vez para evitar esquecer o PDF ou enviar a atividade sem anexo.'}</p></div><span class="delivery-format">${CLASSROOM_CONFIG.deliveryType}</span></div><div class="delivery-status-grid">${steps}</div><div class="delivery-file-callout ${current==='resultExported'?'active':''}"><span>PDF esperado</span><strong>${esc(file)}</strong><small>O navegador normalmente salva esse arquivo na pasta Downloads.</small></div><div class="hero-actions delivery-actions"><button class="btn btn-primary delivery-main-action ${current==='resultExported'&&ready?'attention-pulse':''}" data-delivery-pdf ${!ready?'disabled':''}>${!ready?`PDF disponível em ${formatDuration(pdfReleaseRemaining(record))}`:(d.resultExported?'Baixar o PDF novamente':'1. Baixar resultado em PDF')}</button><button class="btn btn-secondary ${current==='classroomOpened'?'attention-pulse':''}" data-delivery-classroom ${!d.resultExported?'disabled':''}>2. Ver instruções e abrir Classroom</button><button class="btn btn-secondary" data-delivery-help>Ver passo a passo completo</button><button class="btn btn-secondary" data-back-guided>${kind==='guided'?'Voltar às aulas':'Novo diagnóstico'}</button></div>${current==='complete'?'<div class="delivery-success"><b>✓</b><div><strong>Confirmação final registrada.</strong><span>Guarde o PDF até o professor conferir a atividade no Classroom.</span></div></div>':''}</section>`
}
function bindDeliveryHub(root,record,kind){
  const hub=root.querySelector('.delivery-hub');if(!hub)return;
  record.delivery||={resultExported:false,classroomOpened:false,attachedConfirmed:false,deliveredConfirmed:false};
  const syncGuidedLog=(type,label,detail='')=>{if(kind!=='guided'||!state.lessonRuntime)return;logLessonActivity(type,label,detail);record.activityLog=(state.lessonRuntime.activityLog||[]).slice(-300);record.interactions=state.lessonRuntime.interactions;record.tutorial={enabledAtFinish:Boolean(state.lessonRuntime.tutorialEnabled),openCount:Number(state.lessonRuntime.tutorialOpens)||0}};
  const persist=()=>{if(kind==='guided'){state.lessonRuntime.completion=record;saveRuntime()}else{state.result=record;updateResult(record)}};
  const rerender=()=>{persist();if(kind==='guided')renderCompletedLesson(record);else mountResult()};
  const openGuide=({openClassroom=false}={})=>{syncGuidedLog('delivery_help_opened','Passo a passo de entrega consultado','Instruções para baixar, anexar e entregar o PDF no Google Classroom.');persist();const modal=document.createElement('div');modal.className='modal';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.innerHTML=deliveryGuideHTML(record,kind,{opening:openClassroom});document.body.appendChild(modal);const close=()=>modal.remove();modal.querySelector('[data-classroom-guide-close]').onclick=close;modal.querySelector('[data-classroom-guide-open]')?.addEventListener('click',()=>{record.delivery.classroomOpened=true;syncGuidedLog('classroom_opened','Google Classroom aberto após leitura das instruções','O estudante consultou o passo a passo antes de abrir o Classroom.');persist();close();window.open(safeUrl(CLASSROOM_CONFIG.activityUrl||CLASSROOM_CONFIG.generalUrl,{allowHttp:false,allowRelative:false})||'https://classroom.google.com/','_blank','noopener,noreferrer');toast(CLASSROOM_CONFIG.directActivityConfigured?'Atividade aberta em nova guia.':'Classroom aberto. Entre na turma e localize a atividade indicada pelo professor.','good',6000);rerender()})};
  hub.querySelector('[data-delivery-pdf]').onclick=async e=>{if(kind==='guided'&&!pdfReleaseReady(record)){toast(`O PDF será liberado em ${formatDuration(pdfReleaseRemaining(record))} ou com o código coletivo do professor.`,'warn',5000);return}const b=e.currentTarget,txt=b.textContent;b.disabled=true;b.textContent='Criando arquivo PDF…';try{syncGuidedLog('pdf_export_requested','Download do resultado solicitado','O estudante iniciou a criação do PDF para anexar no Classroom.');persist();if(kind==='guided'){if(!record.teacherRelease?.authorized)registerAutomaticPdfRelease(record,record.pdfReleaseReason==='minimum-already-met'?'minimum-already-met':'automatic-session-time');persist();await downloadCompletionPDF(record,deliveryFileName(record,kind))}else await downloadResultPDF(record,deliveryFileName(record,kind));record.delivery.resultExported=true;record.delivery.resultExportedAt=now();syncGuidedLog('pdf_export_completed','Resultado em PDF baixado','Arquivo criado no dispositivo; próximo passo: abrir as instruções do Classroom.');persist();toast('PDF baixado. Agora leia as instruções e abra o Google Classroom.','good',6000);rerender()}catch(err){console.error(err);syncGuidedLog('pdf_export_failed','Falha ao baixar resultado em PDF',String(err?.message||'Erro local de geração.'));persist();toast('Não foi possível gerar o PDF neste aparelho.','bad')}finally{b.disabled=false;b.textContent=txt}};
  hub.querySelector('[data-delivery-classroom]').onclick=()=>{if(!record.delivery.resultExported){toast('Primeiro baixe o resultado em PDF.','warn');return}openGuide({openClassroom:true})};
  hub.querySelector('[data-delivery-state="resultExported"]').onclick=()=>hub.querySelector('[data-delivery-pdf]').click();
  hub.querySelector('[data-delivery-state="classroomOpened"]').onclick=()=>hub.querySelector('[data-delivery-classroom]').click();
  hub.querySelector('[data-delivery-state="attachedConfirmed"]')?.addEventListener('click',()=>{if(!record.delivery.resultExported||!record.delivery.classroomOpened){toast('Baixe o PDF e abra o Classroom antes de confirmar o anexo.','warn');return}const confirming=!record.delivery.attachedConfirmed;if(confirming&&!confirm('O nome do PDF já apareceu anexado na área “Seu trabalho” do Google Classroom?'))return;record.delivery.attachedConfirmed=confirming;record.delivery.attachedConfirmedAt=confirming?now():'';if(!confirming){record.delivery.deliveredConfirmed=false;record.delivery.deliveredConfirmedAt=''}syncGuidedLog(confirming?'attachment_confirmed':'attachment_unconfirmed',confirming?'Aluno confirmou que o PDF foi anexado':'Confirmação de anexo removida',confirming?'O aluno declarou que aguardou o upload e visualizou o arquivo anexado no Classroom.':'O estudante voltou para corrigir o anexo.');rerender()});
  hub.querySelector('[data-delivery-state="deliveredConfirmed"]')?.addEventListener('click',()=>{if(!record.delivery.attachedConfirmed){toast('Primeiro confirme que o PDF foi anexado e terminou de carregar.','warn');return}const confirming=!record.delivery.deliveredConfirmed;if(confirming&&!confirm('Você clicou em “Entregar” ou “Marcar como concluída” e confirmou no Google Classroom?'))return;record.delivery.deliveredConfirmed=confirming;record.delivery.deliveredConfirmedAt=confirming?now():'';syncGuidedLog(confirming?'delivery_confirmed':'delivery_unconfirmed',confirming?'Entrega final confirmada pelo estudante':'Confirmação final removida',confirming?'Registro declaratório: o aluno informou que clicou em Entregar no Classroom.':'O estudante voltou para revisar a entrega.');rerender()});
  hub.querySelector('[data-delivery-help]').onclick=()=>openGuide({openClassroom:false});
  hub.querySelector('[data-back-guided]').onclick=()=>kind==='guided'?setView('guided'):setView('diagnosticSetup')
}

function applySettings(){document.documentElement.style.setProperty('--font-scale',state.settings.fontScale);const requested=state.settings.theme||'dark';const resolved=requested==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):requested;document.body.classList.remove('theme-dark','theme-light');document.body.classList.add(`theme-${resolved}`);document.body.classList.toggle('high-contrast',state.settings.highContrast);document.body.classList.toggle('reduced-motion',state.settings.reducedMotion);document.body.classList.toggle('reading-mode',state.settings.readingMode);const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=resolved==='light'?'#eef3fb':'#030812'}

let pendingServiceWorker=null,allowServiceWorkerReload=false,updatePromptOpen=false;
function activityInProgress(){return Boolean((state.lessonRuntime&&!state.lessonRuntime.completed)||state.diag&&!state.diag.finished)}
function maybePromptPendingUpdate(){if(!pendingServiceWorker||updatePromptOpen||activityInProgress())return;updatePromptOpen=true;const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><span class="hero-kicker">ATUALIZAÇÃO DISPONÍVEL</span><h2>Atualizar a plataforma com segurança</h2><p>Seu progresso será salvo antes da atualização. Durante uma aula ou teste, a atualização fica adiada automaticamente.</p><div class="stage-actions"><button class="btn btn-secondary" data-update-later>Depois</button><button class="btn btn-primary" data-update-now>Salvar e atualizar</button></div></div>`;document.body.appendChild(modal);modal.querySelector('[data-update-later]').onclick=()=>{updatePromptOpen=false;modal.remove()};modal.querySelector('[data-update-now]').onclick=async()=>{const button=modal.querySelector('[data-update-now]');button.disabled=true;button.textContent='Salvando…';await saveRuntime();if(state.diag)await persistDiagnostic();await flushStorage();allowServiceWorkerReload=true;pendingServiceWorker.postMessage({type:'SKIP_WAITING'})}}
if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.addEventListener('controllerchange',()=>{if(allowServiceWorkerReload)location.reload()});navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{const watch=worker=>worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){pendingServiceWorker=worker;if(activityInProgress())toast('Nova versão pronta. Ela será aplicada depois de salvar e sair da atividade.','warn',7000);else maybePromptPendingUpdate()}});if(reg.waiting){pendingServiceWorker=reg.waiting;maybePromptPendingUpdate()}watch(reg.installing);reg.addEventListener('updatefound',()=>watch(reg.installing));reg.update()}).catch(error=>console.warn('Modo offline não pôde ser ativado.',error))})}
